from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from .git import find_repo_root
from .models import CoverageEvent, LineRange


def import_agent_coverage(
    path: Path, *, cwd: Path | None = None
) -> tuple[Path, list[CoverageEvent]]:
    root = find_repo_root(cwd or Path.cwd())
    data = json.loads(path.read_text(encoding="utf-8"))
    events: list[CoverageEvent] = []
    if isinstance(data, list):
        for item in data:
            if isinstance(item, dict):
                events.extend(_events_from_coverage_item(item, root=root, task_path=[]))
    elif isinstance(data, dict):
        for task in data.get("tasks", []):
            if isinstance(task, dict):
                events.extend(_walk_task(task, root=root, task_path=[]))
        for item in data.get("coverage", []):
            if isinstance(item, dict):
                events.extend(_events_from_coverage_item(item, root=root, task_path=[]))
    else:
        raise ValueError("unsupported import format")
    return root, events


def _walk_task(task: dict[str, Any], *, root: Path, task_path: list[str]) -> list[CoverageEvent]:
    label = str(task.get("prompt") or task.get("kind") or "task")
    next_path = [*task_path, label]
    events: list[CoverageEvent] = []
    for item in task.get("coverage", []):
        if isinstance(item, dict):
            events.extend(_events_from_coverage_item(item, root=root, task_path=next_path))
    for child in task.get("children", []):
        if isinstance(child, dict):
            events.extend(_walk_task(child, root=root, task_path=next_path))
    return events


def _events_from_coverage_item(
    item: dict[str, Any], *, root: Path, task_path: list[str]
) -> list[CoverageEvent]:
    command = item.get("cmd") or item.get("command")
    events = []
    for raw_range in item.get("ranges", []):
        parsed = _parse_range(str(raw_range))
        if not parsed:
            continue
        file, start, end = parsed
        events.append(
            CoverageEvent(
                repo_root=str(root),
                agent="import",
                source="agent-coverage-import",
                tool_name="import",
                command=str(command) if command else None,
                file=file,
                ranges=[LineRange(start, end)],
                kind="read",
                confidence="exact",
                task_path=task_path,
            )
        )
    return events


def _parse_range(value: str) -> tuple[str, int, int] | None:
    parts = value.rsplit(":", 2)
    if len(parts) == 2:
        file, start = parts
        end = start
    elif len(parts) == 3:
        file, start, end = parts
    else:
        return None
    try:
        parsed_start = int(start)
        parsed_end = int(end)
    except ValueError:
        return None
    if not file or parsed_start < 1 or parsed_end < parsed_start:
        return None
    return file, parsed_start, parsed_end

from __future__ import annotations

import json
from pathlib import Path
from typing import Any


def read_jsonl(path: Path) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    with path.open("r", encoding="utf-8") as file:
        for line in file:
            if not line.strip():
                continue
            try:
                record = json.loads(line)
            except json.JSONDecodeError:
                continue
            if isinstance(record, dict):
                records.append(record)
    return records


def find_codex_session_matches(session_id: str) -> list[Path]:
    sessions_root = Path.home() / ".codex" / "sessions"
    if not sessions_root.exists():
        return []
    return sorted(sessions_root.rglob(f"*{session_id}*.jsonl"))


def find_claude_session_matches(session_id: str) -> list[Path]:
    sessions_root = Path.home() / ".claude" / "projects"
    if not sessions_root.exists():
        return []
    matches = sorted(sessions_root.rglob(f"*{session_id}*.jsonl"))
    return [path for path in matches if "/subagents/" not in path.as_posix()]


def find_pi_session_matches(session_id: str) -> list[Path]:
    agent_root = Path.home() / ".pi" / "agent"
    sessions_root = agent_root / "sessions"
    matches: list[Path] = []
    if sessions_root.exists():
        matches.extend(sorted(sessions_root.rglob(f"*{session_id}*.jsonl")))
    if agent_root.exists():
        matches.extend(sorted(agent_root.glob(f"*{session_id}*.jsonl")))
    return sorted(dict.fromkeys(matches))


def claude_session_paths_from_transcript(path: Path) -> list[Path]:
    paths = [path]
    subagents = path.with_suffix("") / "subagents"
    if subagents.exists():
        paths.extend(sorted(subagents.glob("*.jsonl")))
    return paths


def pi_session_paths_from_transcript(path: Path) -> list[Path]:
    paths = [path]
    seen = {path.resolve()}
    queue = [path.resolve()]
    candidates = _pi_candidate_paths(path)
    while queue:
        parent = queue.pop(0)
        for candidate in candidates:
            resolved = candidate.resolve()
            if resolved in seen:
                continue
            parent_session = _pi_parent_session(candidate)
            if parent_session is None:
                continue
            try:
                if parent_session.resolve() != parent:
                    continue
            except OSError:
                continue
            seen.add(resolved)
            paths.append(candidate)
            queue.append(resolved)
    return paths


def _pi_candidate_paths(path: Path) -> list[Path]:
    root = _pi_sessions_root_for_path(path)
    if root and root.exists():
        return sorted(root.rglob("*.jsonl"))
    return sorted(path.parent.rglob("*.jsonl")) if path.parent.exists() else []


def _pi_sessions_root_for_path(path: Path) -> Path | None:
    sessions_root = Path.home() / ".pi" / "agent" / "sessions"
    try:
        path.resolve().relative_to(sessions_root.resolve())
    except (OSError, ValueError):
        return None
    return sessions_root


def _pi_parent_session(path: Path) -> Path | None:
    try:
        with path.open("r", encoding="utf-8") as file:
            for line in file:
                if not line.strip():
                    continue
                record = json.loads(line)
                break
            else:
                return None
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(record, dict) or record.get("type") != "session":
        return None
    parent = record.get("parentSession") or record.get("branchedFrom")
    if not isinstance(parent, str) or not parent:
        return None
    return Path(parent).expanduser()

from __future__ import annotations

from pathlib import Path

from .claude_transcript import looks_like_claude_transcript, payloads_from_claude_records
from .codex_transcript import payloads_from_codex_record
from .hooks import events_from_payload
from .models import CoverageEvent, coverage_event_identity
from .pi_transcript import looks_like_pi_transcript, payloads_from_pi_records
from .transcripts import (
    claude_session_paths_from_transcript,
    find_claude_session_matches,
    find_codex_session_matches,
    find_pi_session_matches,
    pi_session_paths_from_transcript,
    read_jsonl,
)


def backfill_codex_session(
    *,
    session_id: str | None = None,
    transcript_path: Path | None = None,
) -> tuple[Path, list[CoverageEvent]]:
    path = transcript_path or _find_codex_session(session_id)
    events: list[CoverageEvent] = []
    seen: set[tuple[object, ...]] = set()
    root = Path.cwd().resolve()
    for record in read_jsonl(path):
        for payload in payloads_from_codex_record(record):
            root, parsed_events = events_from_payload(payload, source="transcript-backfill")
            _extend_new_events(events, parsed_events, seen)
    return root, events


def backfill_claude_session(
    *,
    session_id: str | None = None,
    transcript_path: Path | None = None,
) -> tuple[Path, list[CoverageEvent]]:
    paths = (
        claude_session_paths_from_transcript(transcript_path)
        if transcript_path
        else _find_claude_session_paths(session_id)
    )
    events: list[CoverageEvent] = []
    seen: set[tuple[object, ...]] = set()
    root = Path.cwd().resolve()
    for path in paths:
        records = read_jsonl(path)
        for payload in payloads_from_claude_records(records):
            root, parsed_events = events_from_payload(
                payload,
                source="transcript-backfill",
                agent="claude",
            )
            _extend_new_events(events, parsed_events, seen)
    return root, events


def backfill_pi_session(
    *,
    session_id: str | None = None,
    transcript_path: Path | None = None,
) -> tuple[Path, list[CoverageEvent]]:
    paths = (
        pi_session_paths_from_transcript(transcript_path)
        if transcript_path
        else _find_pi_session_paths(session_id)
    )
    events: list[CoverageEvent] = []
    seen: set[tuple[object, ...]] = set()
    root = Path.cwd().resolve()
    for path in paths:
        records = read_jsonl(path)
        for payload in payloads_from_pi_records(records):
            root, parsed_events = events_from_payload(
                payload,
                source="transcript-backfill",
                agent="pi",
            )
            _extend_new_events(events, parsed_events, seen)
    return root, events


def backfill_session(
    *,
    agent: str,
    session_id: str | None = None,
    transcript_path: Path | None = None,
) -> tuple[Path, list[CoverageEvent]]:
    selected = (
        _infer_agent(session_id=session_id, transcript_path=transcript_path)
        if agent == "auto"
        else agent
    )
    if selected == "codex":
        return backfill_codex_session(session_id=session_id, transcript_path=transcript_path)
    if selected == "claude":
        return backfill_claude_session(session_id=session_id, transcript_path=transcript_path)
    if selected == "pi":
        return backfill_pi_session(session_id=session_id, transcript_path=transcript_path)
    raise ValueError(f"unsupported agent: {selected}")


def _find_codex_session(session_id: str | None) -> Path:
    if not session_id:
        raise ValueError("provide --session-id or --path")
    matches = find_codex_session_matches(session_id)
    if not matches:
        raise FileNotFoundError(f"no Codex session JSONL found for {session_id!r}")
    return matches[-1]


def _find_claude_session_paths(session_id: str | None) -> list[Path]:
    if not session_id:
        raise ValueError("provide --session-id or --path")
    matches = find_claude_session_matches(session_id)
    if not matches:
        raise FileNotFoundError(f"no Claude session JSONL found for {session_id!r}")
    return claude_session_paths_from_transcript(matches[-1])


def _find_pi_session_paths(session_id: str | None) -> list[Path]:
    if not session_id:
        raise ValueError("provide --session-id or --path")
    matches = find_pi_session_matches(session_id)
    if not matches:
        raise FileNotFoundError(f"no Pi session JSONL found for {session_id!r}")
    return pi_session_paths_from_transcript(matches[-1])


def _extend_new_events(
    events: list[CoverageEvent],
    parsed_events: list[CoverageEvent],
    seen: set[tuple[object, ...]],
) -> None:
    for event in parsed_events:
        key = coverage_event_identity(event)
        if key in seen:
            continue
        seen.add(key)
        events.append(event)


def _infer_agent(*, session_id: str | None, transcript_path: Path | None) -> str:
    if transcript_path:
        records = read_jsonl(transcript_path)
        detected = _detect_agent_from_records(records)
        if detected:
            return detected
        path_text = transcript_path.expanduser().as_posix()
        if "/.claude/" in path_text:
            return "claude"
        if "/.codex/" in path_text:
            return "codex"
        if "/.pi/" in path_text:
            return "pi"
    if session_id:
        codex_matches = find_codex_session_matches(session_id)
        claude_matches = find_claude_session_matches(session_id)
        pi_matches = find_pi_session_matches(session_id)
        if claude_matches and not codex_matches and not pi_matches:
            return "claude"
        if codex_matches and not claude_matches and not pi_matches:
            return "codex"
        if pi_matches and not codex_matches and not claude_matches:
            return "pi"
        if codex_matches or claude_matches or pi_matches:
            classified = [
                (_detect_agent_from_records(read_jsonl(path)), path)
                for path in [*codex_matches, *claude_matches, *pi_matches]
            ]
            detected = [(agent, path) for agent, path in classified if agent]
            if detected:
                return max(detected, key=lambda item: item[1].stat().st_mtime)[0]
            if pi_matches:
                return "pi"
            return "claude" if claude_matches else "codex"
        raise FileNotFoundError(f"no Codex, Claude, or Pi session JSONL found for {session_id!r}")
    return "codex"


def _detect_agent_from_records(records: list[dict[str, object]]) -> str | None:
    if any(payloads_from_codex_record(record) for record in records):
        return "codex"
    if looks_like_claude_transcript(records):
        return "claude"
    if looks_like_pi_transcript(records):
        return "pi"
    if any(record.get("type") == "response_item" for record in records):
        return "codex"
    return None

from __future__ import annotations

import tomllib
from dataclasses import dataclass, field
from fnmatch import fnmatchcase
from pathlib import Path
from typing import Any

DEFAULT_EXCLUDES = [
    ".agentcov/",
    "node_modules/",
    "vendor/",
    "dist/",
    "build/",
    ".next/",
    "coverage/",
    ".git/",
    ".venv/",
]


@dataclass(frozen=True)
class AgentcovConfig:
    storage_dir: str = ".agentcov"
    exclude: tuple[str, ...] = field(default_factory=lambda: tuple(DEFAULT_EXCLUDES))
    include_lockfiles: bool = True
    auto_reports: tuple[str, ...] = ("json",)


def load_config(root: Path | str | None = None) -> AgentcovConfig:
    base = Path(root or ".").resolve()
    path = base / ".agentcov.toml"
    if not path.exists():
        return AgentcovConfig()
    data = tomllib.loads(path.read_text(encoding="utf-8"))
    raw_section = data.get("agentcov", data)
    if not isinstance(raw_section, dict):
        raise ValueError(f"{path}: [agentcov] config must be a table")
    section: dict[str, Any] = raw_section
    excludes = _string_tuple(section.get("exclude", DEFAULT_EXCLUDES), field_name="exclude")
    auto_reports = _string_tuple(section.get("auto_reports", ("json",)), field_name="auto_reports")
    return AgentcovConfig(
        storage_dir=str(section.get("storage_dir", ".agentcov")),
        exclude=excludes,
        include_lockfiles=bool(section.get("include_lockfiles", True)),
        auto_reports=auto_reports,
    )


def is_excluded(relpath: str, config: AgentcovConfig) -> bool:
    normalized = _normalize_relpath(relpath)
    storage_dir = config.storage_dir.strip().replace("\\", "/").strip("/")
    storage_patterns = (f"{storage_dir}/",) if storage_dir else ()
    for pattern in (*storage_patterns, *config.exclude):
        if _matches_exclude(normalized, pattern):
            return True
    return not config.include_lockfiles and _is_lockfile(normalized)


def _matches_exclude(relpath: str, pattern: str) -> bool:
    raw_pattern = pattern.strip().replace("\\", "/")
    while raw_pattern.startswith("./"):
        raw_pattern = raw_pattern[2:]
    anchored = raw_pattern.startswith("/")
    normalized = raw_pattern.lstrip("/")
    if not normalized.endswith("/"):
        normalized = normalized.strip("/")
    if not normalized:
        return False
    if normalized.endswith("/"):
        directory = normalized.strip("/")
        if not directory:
            return False
        if anchored:
            return relpath == directory or relpath.startswith(f"{directory}/")
        padded_path = f"/{relpath.strip('/')}/"
        return (
            relpath == directory
            or relpath.startswith(f"{directory}/")
            or f"/{directory}/" in padded_path
        )

    candidates = [relpath]
    if "/" not in normalized:
        candidates.append(Path(relpath).name)
    if any(char in normalized for char in "*?[]"):
        if any(fnmatchcase(candidate, normalized) for candidate in candidates):
            return True
        if not anchored and "/" in normalized:
            return fnmatchcase(relpath, f"*/{normalized}")
        return False
    return relpath == normalized or (
        not anchored and "/" not in normalized and Path(relpath).name == normalized
    )


def _normalize_relpath(path: str) -> str:
    normalized = path.strip().replace("\\", "/")
    while normalized.startswith("./"):
        normalized = normalized[2:]
    if normalized.endswith("/") and normalized != "/":
        return normalized
    return normalized.strip("/")


def _string_tuple(value: object, *, field_name: str) -> tuple[str, ...]:
    if isinstance(value, str) or not isinstance(value, list | tuple):
        raise ValueError(f"{field_name} must be a list of strings")
    return tuple(str(item) for item in value)


def _is_lockfile(path: str) -> bool:
    name = Path(path).name
    return name in {
        "package-lock.json",
        "pnpm-lock.yaml",
        "yarn.lock",
        "poetry.lock",
        "uv.lock",
        "Cargo.lock",
        "Gemfile.lock",
    }

from __future__ import annotations

import json
import re
from typing import Any

_EXEC_COMMAND_CALL = re.compile(r"\btools\.exec_command\(\s*(?=\{)")
_IDENTIFIER = re.compile(r"[A-Za-z_$][A-Za-z0-9_$]*")
_NUMBER = re.compile(r"-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][-+]?[0-9]+)?")
_STRING_ESCAPES = {"b": "\b", "f": "\f", "n": "\n", "r": "\r", "t": "\t", "v": "\v", "0": "\0"}


class _NotALiteral(Exception):
    """Raised when a JavaScript value is not a self-contained literal."""


def payloads_from_codex_record(record: dict[str, Any]) -> list[dict[str, Any]]:
    payloads: list[dict[str, Any]] = []
    if _looks_like_tool_payload(record):
        payloads.append(record)
    for key in ("item", "payload"):
        child = record.get(key)
        if isinstance(child, dict):
            payloads.extend(_payloads_from_child_record(record, child))
    return payloads


def _looks_like_tool_payload(record: dict[str, Any]) -> bool:
    return any(key in record for key in ("tool_name", "tool_input", "command", "cmd"))


def _payloads_from_child_record(
    record: dict[str, Any],
    child: dict[str, Any],
) -> list[dict[str, Any]]:
    payloads: list[dict[str, Any]] = []
    if _looks_like_tool_payload(child):
        payloads.append({**record, **child})
    name = child.get("name")
    if not isinstance(name, str):
        return payloads
    payloads.extend(
        {
            **record,
            "tool_name": name,
            "tool_input": tool_input,
            "tool_response": child.get("output") or record.get("output"),
            "tool_use_id": child.get("call_id") or record.get("tool_use_id"),
        }
        for tool_input in _tool_inputs_from_child(child, name)
    )
    return payloads


def _tool_inputs_from_child(child: dict[str, Any], name: str) -> list[object]:
    arguments = child.get("arguments")
    if arguments is not None:
        return [_parse_tool_arguments(arguments)]
    source = child.get("input")
    # A `custom_tool_call` carries a JavaScript program instead of arguments.
    # Only `tools.exec_command` names a command; `apply_patch`, `write_stdin`
    # and the rest either write or do not touch files at all.
    if child.get("type") == "custom_tool_call" and name == "exec" and isinstance(source, str):
        return _exec_command_arguments(source)
    return []


def _parse_tool_arguments(arguments: object) -> object:
    if isinstance(arguments, str):
        try:
            return json.loads(arguments)
        except json.JSONDecodeError:
            return {"command": arguments}
    return arguments


def _exec_command_arguments(source: str) -> list[object]:
    arguments: list[object] = []
    for match in _EXEC_COMMAND_CALL.finditer(source):
        try:
            value, _ = _read_object(source, match.end())
        except _NotALiteral:
            # Interpolated or computed arguments cannot be resolved without
            # running the program, so the call is skipped rather than guessed.
            continue
        arguments.append(value)
    return arguments


def _read_value(source: str, index: int) -> tuple[Any, int]:
    index = _skip_whitespace(source, index)
    if index >= len(source):
        raise _NotALiteral
    char = source[index]
    if char == "{":
        return _read_object(source, index)
    if char == "[":
        return _read_array(source, index)
    if char in "\"'":
        return _read_string(source, index)
    for word, value in (("true", True), ("false", False), ("null", None)):
        end = index + len(word)
        if source.startswith(word, index) and not _IDENTIFIER.match(source, end):
            return value, end
    number = _NUMBER.match(source, index)
    if number:
        return json.loads(number.group()), number.end()
    raise _NotALiteral


def _read_object(source: str, index: int) -> tuple[dict[str, Any], int]:
    index = _skip_whitespace(source, index + 1)
    entries: dict[str, Any] = {}
    if index < len(source) and source[index] == "}":
        return entries, index + 1
    while True:
        index = _skip_whitespace(source, index)
        if index < len(source) and source[index] in "\"'":
            key, index = _read_string(source, index)
        else:
            identifier = _IDENTIFIER.match(source, index)
            if not identifier:
                raise _NotALiteral
            key, index = identifier.group(), identifier.end()
        index = _skip_whitespace(source, index)
        if index >= len(source) or source[index] != ":":
            raise _NotALiteral
        entries[key], index = _read_value(source, index + 1)
        index, done = _read_separator(source, index, close="}")
        if done:
            return entries, index


def _read_array(source: str, index: int) -> tuple[list[Any], int]:
    index = _skip_whitespace(source, index + 1)
    items: list[Any] = []
    if index < len(source) and source[index] == "]":
        return items, index + 1
    while True:
        value, index = _read_value(source, index)
        items.append(value)
        index, done = _read_separator(source, index, close="]")
        if done:
            return items, index


def _read_separator(source: str, index: int, *, close: str) -> tuple[int, bool]:
    """Consume the `,` or closing bracket after an element. Returns whether it closed."""
    index = _skip_whitespace(source, index)
    if index >= len(source):
        raise _NotALiteral
    if source[index] == close:
        return index + 1, True
    if source[index] != ",":
        raise _NotALiteral
    index = _skip_whitespace(source, index + 1)
    if index < len(source) and source[index] == close:
        return index + 1, True
    return index, False


def _read_string(source: str, index: int) -> tuple[str, int]:
    quote = source[index]
    index += 1
    parts: list[str] = []
    while index < len(source):
        char = source[index]
        if char == quote:
            return "".join(parts), index + 1
        if char == "\n":
            raise _NotALiteral
        if char != "\\":
            parts.append(char)
            index += 1
            continue
        index += 1
        if index >= len(source):
            break
        escape = source[index]
        if escape in "ux":
            width = 4 if escape == "u" else 2
            try:
                parts.append(chr(int(source[index + 1 : index + 1 + width], 16)))
            except ValueError:
                raise _NotALiteral from None
            index += 1 + width
            continue
        if escape != "\n":
            parts.append(_STRING_ESCAPES.get(escape, escape))
        index += 1
    raise _NotALiteral


def _skip_whitespace(source: str, index: int) -> int:
    while index < len(source) and source[index] in " \t\r\n":
        index += 1
    return index

from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from .config import AgentcovConfig, is_excluded, load_config
from .git import file_line_count, git_metadata, inventory_hash, list_project_files
from .models import Confidence, CoverageEvent, LineRange
from .paths import display_command


@dataclass
class LineStats:
    read_count: int = 0
    unique_read_count: int = 0
    search_seen_count: int = 0
    search_hit_count: int = 0
    search_context_count: int = 0
    attention_score: float = 0.0
    first_read_at: str | None = None
    last_read_at: str | None = None
    commands: list[str] = field(default_factory=list)
    events: list[str] = field(default_factory=list)
    attributions: list[dict[str, Any]] = field(default_factory=list)
    confidence: str = "exact"

    def to_json(self) -> dict[str, Any]:
        return {
            "read_count": self.read_count,
            "unique_read_count": self.unique_read_count,
            "search_seen_count": self.search_seen_count,
            "search_hit_count": self.search_hit_count,
            "search_context_count": self.search_context_count,
            "attention_score": round(self.attention_score, 4),
            "first_read_at": self.first_read_at,
            "last_read_at": self.last_read_at,
            "commands": self.commands,
            "events": self.events,
            "attributions": self.attributions,
            "confidence": self.confidence,
        }


@dataclass
class FileCoverage:
    path: str
    line_count: int
    lines: dict[int, LineStats] = field(default_factory=dict)
    read_ranges: list[dict[str, Any]] = field(default_factory=list)
    search_seen_ranges: list[dict[str, Any]] = field(default_factory=list)

    @property
    def read_lines(self) -> int:
        return sum(1 for stats in self.lines.values() if stats.read_count > 0)

    @property
    def search_seen_lines(self) -> int:
        return sum(1 for stats in self.lines.values() if stats.search_seen_count > 0)

    @property
    def search_hit_lines(self) -> int:
        return sum(1 for stats in self.lines.values() if stats.search_hit_count > 0)

    @property
    def search_context_lines(self) -> int:
        return sum(1 for stats in self.lines.values() if stats.search_context_count > 0)

    @property
    def read_percent(self) -> float:
        if self.line_count <= 0:
            return 100.0
        return round((self.read_lines / self.line_count) * 100, 2)

    def count_for_line(self, line: int, *, mode: str = "full") -> int:
        stats = self.lines.get(line)
        count = stats.read_count if stats else 0
        if mode == "binary":
            return 1 if count else 0
        return count

    def unread_ranges(self) -> list[tuple[int, int]]:
        ranges: list[tuple[int, int]] = []
        start: int | None = None
        for line in range(1, self.line_count + 1):
            if self.count_for_line(line, mode="binary") == 0:
                if start is None:
                    start = line
            elif start is not None:
                ranges.append((start, line - 1))
                start = None
        if start is not None:
            ranges.append((start, self.line_count))
        return ranges

    def to_json(self, *, include_zero_lines: bool = False) -> dict[str, Any]:
        if include_zero_lines:
            line_data = {
                str(line): self.lines.get(line, LineStats()).to_json()
                for line in range(1, self.line_count + 1)
            }
        else:
            line_data = {
                str(line): stats.to_json()
                for line, stats in sorted(self.lines.items())
                if stats.read_count or stats.search_seen_count
            }
        return {
            "path": self.path,
            "line_count": self.line_count,
            "read_lines": self.read_lines,
            "search_seen_lines": self.search_seen_lines,
            "search_hit_lines": self.search_hit_lines,
            "search_context_lines": self.search_context_lines,
            "read_percent": self.read_percent,
            "unread_ranges": [{"start": start, "end": end} for start, end in self.unread_ranges()],
            "read_ranges": self.read_ranges,
            "search_seen_ranges": self.search_seen_ranges,
            "lines": line_data,
        }


def build_coverage(
    *,
    root: Path,
    events: list[CoverageEvent],
    config: AgentcovConfig | None = None,
) -> dict[str, Any]:
    cfg = config or load_config(root)
    inventory = list_project_files(root, cfg)
    files: dict[str, FileCoverage] = {
        rel: FileCoverage(path=rel, line_count=file_line_count(_source_path(root, rel)))
        for rel in inventory
    }
    unknown_events: list[dict[str, Any]] = []

    for event in events:
        if event.kind == "unknown" or not event.file or not event.ranges:
            unknown_events.append(_event_summary(event))
            continue
        rel = _event_file_key(event.file, root=root, config=cfg)
        if rel is None:
            unknown_events.append(
                _event_summary(event, reason="file is excluded or outside coverage scope")
            )
            continue
        if rel not in files:
            path = _source_path(root, rel)
            line_count = file_line_count(path)
            if line_count <= 0:
                unknown_events.append(
                    _event_summary(event, reason="file is missing, unreadable, or empty")
                )
                continue
            files[rel] = FileCoverage(path=rel, line_count=line_count)
        file_cov = files[rel]
        if file_cov.line_count <= 0:
            unknown_events.append(
                _event_summary(event, reason="file is missing, unreadable, or empty")
            )
            continue
        ranges = (
            _bounded_search_ranges(event.ranges, file_cov.line_count)
            if event.kind == "search_seen"
            else _merged_bounded_ranges(event.ranges, file_cov.line_count)
        )
        for normalized in ranges:
            start = normalized.start
            end = normalized.end
            range_summary = {
                "start": start,
                "end": end,
                "confidence": normalized.confidence,
                "weight": normalized.weight,
                "event_id": event.event_id,
                "command": display_command(event.command),
                "timestamp": event.timestamp,
                "attribution": _event_attribution(event),
            }
            if event.kind == "search_seen":
                range_summary["search_role"] = _search_role(normalized.weight)
                file_cov.search_seen_ranges.append(range_summary)
            else:
                file_cov.read_ranges.append(range_summary)
            for line in range(start, end + 1):
                stats = file_cov.lines.setdefault(line, LineStats(confidence=event.confidence))
                _apply_event_to_line(stats, event, weight=normalized.weight)

    files_json = {path: coverage.to_json() for path, coverage in sorted(files.items())}
    total_lines = sum(coverage.line_count for coverage in files.values())
    read_lines = sum(coverage.read_lines for coverage in files.values())
    search_seen_lines = sum(coverage.search_seen_lines for coverage in files.values())
    search_hit_lines = sum(coverage.search_hit_lines for coverage in files.values())
    search_context_lines = sum(coverage.search_context_lines for coverage in files.values())
    sessions = _session_rollups(events)
    return {
        "schema_version": 1,
        "tool": "agentcov",
        "git": {
            **git_metadata(root),
            "tracked_file_count": len(inventory),
            "tracked_file_inventory_hash": inventory_hash(inventory),
        },
        "summary": {
            "files": len(files),
            "total_lines": total_lines,
            "read_lines": read_lines,
            "search_seen_lines": search_seen_lines,
            "search_hit_lines": search_hit_lines,
            "search_context_lines": search_context_lines,
            "read_percent": round((read_lines / total_lines) * 100, 2) if total_lines else 100.0,
            "events": len(events),
            "sessions": len(sessions),
            "unknown_events": len(unknown_events),
        },
        "sessions": sessions,
        "files": files_json,
        "unknown_events": unknown_events,
    }


def coverage_files(coverage: dict[str, Any]) -> dict[str, FileCoverage]:
    files: dict[str, FileCoverage] = {}
    for path, data in coverage.get("files", {}).items():
        file_cov = FileCoverage(path=path, line_count=int(data.get("line_count", 0)))
        for line_text, stats_data in data.get("lines", {}).items():
            stats = LineStats(
                read_count=int(stats_data.get("read_count", 0)),
                unique_read_count=int(stats_data.get("unique_read_count", 0)),
                search_seen_count=int(stats_data.get("search_seen_count", 0)),
                search_hit_count=int(stats_data.get("search_hit_count", 0)),
                search_context_count=int(stats_data.get("search_context_count", 0)),
                attention_score=float(stats_data.get("attention_score", 0.0)),
                first_read_at=stats_data.get("first_read_at"),
                last_read_at=stats_data.get("last_read_at"),
                commands=list(stats_data.get("commands") or []),
                events=list(stats_data.get("events") or []),
                attributions=list(stats_data.get("attributions") or []),
                confidence=stats_data.get("confidence", "exact"),
            )
            file_cov.lines[int(line_text)] = stats
        file_cov.read_ranges = list(data.get("read_ranges") or [])
        file_cov.search_seen_ranges = list(data.get("search_seen_ranges") or [])
        files[path] = file_cov
    return files


def top_unread_files(coverage: dict[str, Any], *, limit: int | None = None) -> list[dict[str, Any]]:
    rows = []
    for path, file_data in sorted(coverage.get("files", {}).items()):
        line_count = int(file_data.get("line_count", 0))
        read_lines = int(file_data.get("read_lines", 0))
        if line_count and read_lines < line_count:
            rows.append(
                {
                    "path": path,
                    "line_count": line_count,
                    "read_lines": read_lines,
                    "unread_lines": line_count - read_lines,
                    "read_percent": file_data.get("read_percent", 0.0),
                    "unread_ranges": file_data.get("unread_ranges", []),
                }
            )
    return rows if limit is None else rows[:limit]


def _apply_event_to_line(stats: LineStats, event: CoverageEvent, *, weight: float) -> None:
    if event.kind == "search_seen":
        stats.search_seen_count += 1
        if _search_role(weight) == "context":
            stats.search_context_count += 1
        else:
            stats.search_hit_count += 1
    else:
        stats.read_count += 1
        if event.event_id not in stats.events:
            stats.unique_read_count += 1
        stats.attention_score += weight
        if stats.first_read_at is None or event.timestamp < stats.first_read_at:
            stats.first_read_at = event.timestamp
        if stats.last_read_at is None or event.timestamp > stats.last_read_at:
            stats.last_read_at = event.timestamp
    command = display_command(event.command)
    if command and command not in stats.commands and len(stats.commands) < 12:
        stats.commands.append(command)
    if event.event_id not in stats.events and len(stats.events) < 24:
        stats.events.append(event.event_id)
    attribution = _event_attribution(event)
    if attribution and attribution not in stats.attributions and len(stats.attributions) < 24:
        stats.attributions.append(attribution)
    if event.confidence == "unknown":
        stats.confidence = "unknown"
    elif event.confidence == "low" and stats.confidence == "exact":
        stats.confidence = "low"


def _merged_bounded_ranges(ranges: list[LineRange], line_count: int) -> list[LineRange]:
    bounded: list[tuple[int, int, Confidence, float]] = []
    for line_range in ranges:
        normalized = line_range.normalized()
        start = max(1, normalized.start)
        end = min(normalized.end, line_count)
        if end >= start:
            bounded.append((start, end, normalized.confidence, normalized.weight))
    if not bounded:
        return []

    bounded.sort(key=lambda item: (item[0], item[1]))
    merged = [bounded[0]]
    for start, end, confidence, weight in bounded[1:]:
        last_start, last_end, last_confidence, last_weight = merged[-1]
        if start <= last_end + 1:
            merged[-1] = (
                last_start,
                max(last_end, end),
                _least_confident(last_confidence, confidence),
                max(last_weight, weight),
            )
        else:
            merged.append((start, end, confidence, weight))

    return [
        LineRange(start=start, end=end, confidence=confidence, weight=weight)
        for start, end, confidence, weight in merged
    ]


def _bounded_search_ranges(ranges: list[LineRange], line_count: int) -> list[LineRange]:
    by_line: dict[int, tuple[Confidence, float]] = {}
    for line_range in ranges:
        normalized = line_range.normalized()
        start = max(1, normalized.start)
        end = min(normalized.end, line_count)
        for line in range(start, end + 1):
            previous = by_line.get(line)
            if previous is None:
                by_line[line] = (normalized.confidence, normalized.weight)
                continue
            confidence, weight = previous
            by_line[line] = (
                _least_confident(confidence, normalized.confidence),
                max(weight, normalized.weight),
            )
    return [
        LineRange(start=line, end=line, confidence=confidence, weight=weight)
        for line, (confidence, weight) in sorted(by_line.items())
    ]


def _least_confident(left: Confidence, right: Confidence) -> Confidence:
    order = {"exact": 0, "inferred": 1, "low": 2, "unknown": 3}
    return left if order.get(left, 0) >= order.get(right, 0) else right


def _event_summary(event: CoverageEvent, *, reason: str | None = None) -> dict[str, Any]:
    return {
        "event_id": event.event_id,
        "timestamp": event.timestamp,
        "agent": event.agent,
        "source": event.source,
        "session_id": event.session_id,
        "turn_id": event.turn_id,
        "tool_use_id": event.tool_use_id,
        "tool_name": event.tool_name,
        "file": event.file,
        "command": display_command(event.command, limit=300),
        "task_path": event.task_path,
        "reason": reason or event.reason,
        "confidence": event.confidence,
    }


def _event_attribution(event: CoverageEvent) -> dict[str, Any]:
    data = {
        "event_id": event.event_id,
        "timestamp": event.timestamp,
        "agent": event.agent,
        "source": event.source,
        "session_id": event.session_id,
        "turn_id": event.turn_id,
        "tool_use_id": event.tool_use_id,
        "tool_name": event.tool_name,
        "command": display_command(event.command, limit=240),
        "task_path": event.task_path,
        "confidence": event.confidence,
    }
    return {
        key: value
        for key, value in data.items()
        if value is not None and value != "" and value != []
    }


def _session_rollups(events: list[CoverageEvent]) -> list[dict[str, Any]]:
    rollups: dict[tuple[str | None, str], dict[str, Any]] = {}
    for event in events:
        key = (event.session_id, event.agent)
        rollup = rollups.setdefault(
            key,
            {
                "session_id": event.session_id,
                "agent": event.agent,
                "first_seen_at": event.timestamp,
                "last_seen_at": event.timestamp,
                "events": 0,
                "read_events": 0,
                "search_seen_events": 0,
                "unknown_events": 0,
                "sources": set(),
                "task_paths": [],
            },
        )
        rollup["events"] += 1
        if event.kind == "read":
            rollup["read_events"] += 1
        elif event.kind == "search_seen":
            rollup["search_seen_events"] += 1
        else:
            rollup["unknown_events"] += 1
        rollup["first_seen_at"] = min(rollup["first_seen_at"], event.timestamp)
        rollup["last_seen_at"] = max(rollup["last_seen_at"], event.timestamp)
        rollup["sources"].add(event.source)
        if event.task_path and event.task_path not in rollup["task_paths"]:
            rollup["task_paths"].append(event.task_path)

    rows = []
    for rollup in rollups.values():
        rows.append(
            {
                **rollup,
                "sources": sorted(rollup["sources"]),
                "task_paths": rollup["task_paths"][:12],
            }
        )
    return sorted(
        rows,
        key=lambda item: (
            str(item["session_id"] or ""),
            str(item["agent"] or ""),
            str(item["first_seen_at"] or ""),
        ),
    )


def _search_role(weight: float) -> str:
    return "context" if weight < 0.35 else "hit"


def _source_path(root: Path, rel: str) -> Path:
    path = Path(rel)
    return path if path.is_absolute() else root / path


def _event_file_key(raw: str | None, *, root: Path, config: AgentcovConfig) -> str | None:
    if not raw:
        return None
    root_resolved = root.resolve()
    path = Path(raw)
    candidate = path.resolve() if path.is_absolute() else (root_resolved / path).resolve()
    try:
        rel = candidate.relative_to(root_resolved).as_posix()
    except ValueError:
        return None
    if is_excluded(rel, config):
        return None
    return rel

from __future__ import annotations

import re
import shlex
from dataclasses import dataclass
from pathlib import Path, PurePosixPath
from typing import Any


@dataclass(frozen=True)
class _PiHeader:
    session_id: str | None = None
    cwd: str | None = None
    timestamp: str | None = None
    parent_session: str | None = None


@dataclass(frozen=True)
class _PiToolResult:
    tool_use_id: str | None
    tool_name: str | None
    value: object
    is_error: bool = False


def payloads_from_pi_records(records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    header = _pi_header(records)
    results_by_tool_id = _pi_results_by_tool_id(records)

    payloads: list[dict[str, Any]] = []
    last_user_request: str | None = None
    for record in records:
        message = record.get("message")
        if not isinstance(message, dict):
            continue
        role = _string(message.get("role"))
        if role == "user":
            last_user_request = _message_text(message)
            continue
        if role == "assistant":
            payloads.extend(
                _assistant_payloads(
                    header=header,
                    record=record,
                    message=message,
                    user_request=last_user_request,
                    results_by_tool_id=results_by_tool_id,
                )
            )
            continue
        if role == "bashExecution":
            payload = _bash_execution_payload(
                header,
                record,
                message,
                user_request=last_user_request,
            )
            if payload:
                payloads.append(payload)
    return payloads


def looks_like_pi_transcript(records: list[dict[str, Any]]) -> bool:
    if any(_looks_like_pi_header(record) for record in records[:1]):
        return True
    for record in records:
        if record.get("type") != "message" or not isinstance(record.get("message"), dict):
            continue
        message = record["message"]
        if _string(message.get("role")) in {"assistant", "toolResult", "bashExecution"}:
            return True
    return False


def _assistant_payloads(
    *,
    header: _PiHeader,
    record: dict[str, Any],
    message: dict[str, Any],
    user_request: str | None,
    results_by_tool_id: dict[str, _PiToolResult],
) -> list[dict[str, Any]]:
    content = message.get("content")
    if not isinstance(content, list):
        return []
    payloads: list[dict[str, Any]] = []
    for block in content:
        if not isinstance(block, dict) or block.get("type") != "toolCall":
            continue
        tool_name = _string(block.get("name"))
        tool_use_id = _string(block.get("id"))
        if not tool_name or not tool_use_id:
            continue
        payload = _base_payload(
            header=header,
            record=record,
            tool_name=tool_name,
            tool_use_id=tool_use_id,
            user_request=user_request,
        )
        arguments = block.get("arguments")
        payload["tool_input"] = _pi_tool_input(
            tool_name,
            arguments if isinstance(arguments, dict) else {},
            cwd=payload.get("cwd"),
        )
        result = results_by_tool_id.get(tool_use_id)
        if result is not None:
            payload = _payload_with_result(payload, result)
            if payload is None:
                continue
        elif tool_name == "read" and not _has_bounded_read_input(payload.get("tool_input")):
            continue
        payloads.append(payload)
    return payloads


def _payload_with_result(
    payload: dict[str, Any],
    result: _PiToolResult,
) -> dict[str, Any] | None:
    tool_name = payload.get("tool_name")
    if tool_name == "read":
        capped = _cap_pi_read_input(payload.get("tool_input"), result)
        if capped is None:
            return None
        payload["tool_input"] = capped
    elif tool_name == "grep":
        payload["tool_response"] = _normalize_pi_grep_response(payload, result.value)
    else:
        payload["tool_response"] = result.value
    return payload


def _base_payload(
    *,
    header: _PiHeader,
    record: dict[str, Any],
    tool_name: str,
    tool_use_id: str,
    user_request: str | None,
) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "session_id": header.session_id,
        "turn_id": _string(record.get("id")),
        "tool_use_id": tool_use_id,
        "timestamp": _string(record.get("timestamp")) or header.timestamp,
        "cwd": header.cwd,
        "tool_name": tool_name,
        "user_request": user_request,
    }
    subagent = _pi_subagent_label(header)
    if subagent:
        payload["subagent"] = subagent
    return {key: value for key, value in payload.items() if value is not None}


def _bash_execution_payload(
    header: _PiHeader,
    record: dict[str, Any],
    message: dict[str, Any],
    *,
    user_request: str | None,
) -> dict[str, Any] | None:
    command = _string(message.get("command"))
    if not command:
        return None
    payload = {
        "session_id": header.session_id,
        "turn_id": _string(record.get("id")),
        "tool_use_id": _string(record.get("id")),
        "timestamp": _string(record.get("timestamp")) or header.timestamp,
        "cwd": header.cwd,
        "tool_name": "bashExecution",
        "tool_input": {"command": command},
        "tool_response": _string(message.get("output")),
        "user_request": user_request,
    }
    subagent = _pi_subagent_label(header)
    if subagent:
        payload["subagent"] = subagent
    return {key: value for key, value in payload.items() if value is not None}


def _pi_tool_input(tool_name: str, arguments: dict[str, Any], *, cwd: object) -> object:
    if tool_name == "read":
        return _pi_read_tool_input(arguments)
    if tool_name == "grep":
        return {
            "command": _pi_grep_command(arguments),
            "_agentcov_grep_path": _string(arguments.get("path")) or ".",
            "_agentcov_grep_cwd": _string(cwd),
        }
    return arguments


def _pi_read_tool_input(arguments: dict[str, Any]) -> dict[str, Any]:
    normalized = dict(arguments)
    offset = _as_int(normalized.pop("offset", None))
    if offset is not None and "start_line" not in normalized and "line_start" not in normalized:
        normalized["start_line"] = max(1, offset)
    return normalized


def _cap_pi_read_input(tool_input: object, result: _PiToolResult) -> object | None:
    if not isinstance(tool_input, dict):
        return tool_input
    if result.is_error or _looks_like_pi_error(result.value):
        return None
    if _looks_like_pi_image_read(result.value):
        return None
    normalized = dict(tool_input)
    bounds = _pi_read_result_bounds(result.value, normalized)
    if bounds is None:
        if _result_looks_truncated(result.value):
            return None if not _has_bounded_read_input(tool_input) else tool_input
        return tool_input
    start, end = bounds
    if end < start:
        return None
    normalized["start_line"] = start
    normalized["end_line"] = end
    normalized.pop("offset", None)
    normalized.pop("limit", None)
    return normalized


def _pi_read_result_bounds(result: object, tool_input: dict[str, Any]) -> tuple[int, int] | None:
    start = _as_int(tool_input.get("start_line") or tool_input.get("line_start")) or 1
    limit = _as_int(tool_input.get("limit"))
    if limit is not None and limit > 0:
        return start, start + limit - 1

    text = _response_text(result)
    match = re.search(r"Showing lines\s+(\d+)-(\d+)\s+of\s+\d+", text)
    if match:
        return int(match.group(1)), int(match.group(2))
    match = re.search(r"Use offset=(\d+)\s+to continue", text)
    if match:
        return start, max(start, int(match.group(1)) - 1)

    details = result.get("details") if isinstance(result, dict) else None
    truncation = details.get("truncation") if isinstance(details, dict) else None
    if isinstance(truncation, dict):
        output_lines = _as_int(truncation.get("outputLines") or truncation.get("output_lines"))
        if output_lines and output_lines > 0:
            return start, start + output_lines - 1
    return None


def _normalize_pi_grep_response(payload: dict[str, Any], result: object) -> object:
    tool_input = payload.get("tool_input")
    if not isinstance(tool_input, dict):
        return result
    raw_path = _string(tool_input.get("_agentcov_grep_path")) or "."
    text = _response_text(result)
    if not text or raw_path in {"", "."}:
        return result

    lines = []
    changed = False
    for line in text.splitlines():
        rewritten = _rewrite_pi_grep_line(line, raw_path=raw_path, cwd=_string(payload.get("cwd")))
        lines.append(rewritten)
        changed = changed or rewritten != line
    return "\n".join(lines) if changed else result


def _rewrite_pi_grep_line(line: str, *, raw_path: str, cwd: str | None) -> str:
    match = re.match(r"^(.+?)(?P<sep>[:\-])(\d+)(?P<trailing>[:\-].*)$", line)
    if not match:
        return line
    file_part = match.group(1)
    if (
        Path(file_part).is_absolute()
        or file_part == raw_path
        or file_part.startswith(f"{raw_path}/")
    ):
        return line

    replacement = _grep_output_path(file_part, raw_path=raw_path, cwd=cwd)
    if not replacement:
        return line
    return f"{replacement}{match.group('sep')}{match.group(3)}{match.group('trailing')}"


def _grep_output_path(file_part: str, *, raw_path: str, cwd: str | None) -> str | None:
    search_path = Path(raw_path).expanduser()
    if not search_path.is_absolute() and cwd:
        search_path = Path(cwd) / search_path

    if search_path.is_file() or (not search_path.exists() and Path(raw_path).suffix):
        return raw_path

    if Path(raw_path).is_absolute():
        return (search_path / file_part).as_posix()
    return PurePosixPath(raw_path, file_part).as_posix()


def _pi_grep_command(arguments: dict[str, Any]) -> str:
    pattern = _string(arguments.get("pattern")) or ""
    path = _string(arguments.get("path")) or "."
    parts = ["grep", "-R", "-n"]
    if arguments.get("ignoreCase"):
        parts.append("-i")
    if arguments.get("literal"):
        parts.append("-F")
    glob = _string(arguments.get("glob"))
    if glob:
        parts.extend(["--include", glob])
    parts.extend([pattern, path])
    return " ".join(shlex.quote(part) for part in parts)


def _pi_results_by_tool_id(records: list[dict[str, Any]]) -> dict[str, _PiToolResult]:
    results: dict[str, _PiToolResult] = {}
    for record in records:
        message = record.get("message")
        if not isinstance(message, dict) or message.get("role") != "toolResult":
            continue
        tool_use_id = _string(message.get("toolCallId"))
        if not tool_use_id:
            continue
        results[tool_use_id] = _PiToolResult(
            tool_use_id=tool_use_id,
            tool_name=_string(message.get("toolName")),
            value={
                "content": message.get("content"),
                "details": message.get("details"),
                "output": message.get("output"),
            },
            is_error=bool(message.get("isError")),
        )
    return results


def _pi_header(records: list[dict[str, Any]]) -> _PiHeader:
    for record in records:
        if _looks_like_pi_header(record):
            return _PiHeader(
                session_id=_string(record.get("id")),
                cwd=_string(record.get("cwd")),
                timestamp=_string(record.get("timestamp")),
                parent_session=_string(record.get("parentSession"))
                or _string(record.get("branchedFrom")),
            )
    return _PiHeader()


def _looks_like_pi_header(record: dict[str, Any]) -> bool:
    return (
        record.get("type") == "session"
        and isinstance(record.get("id"), str)
        and isinstance(record.get("cwd"), str)
    )


def _pi_subagent_label(header: _PiHeader) -> str | None:
    if not header.parent_session:
        return None
    return f"pi child session {header.session_id}" if header.session_id else "pi child session"


def _message_text(message: dict[str, Any]) -> str | None:
    text = _response_text(message.get("content")).strip()
    return text or None


def _response_text(value: object | None) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        parts: list[str] = []
        for key in ("stdout", "output", "stderr", "text", "content"):
            child = value.get(key)
            if isinstance(child, str):
                parts.append(child)
            elif isinstance(child, list):
                parts.extend(_response_text(item) for item in child)
        return "\n".join(part for part in parts if part)
    if isinstance(value, list):
        return "\n".join(_response_text(item) for item in value)
    return ""


def _result_looks_truncated(result: object) -> bool:
    details = result.get("details") if isinstance(result, dict) else None
    if isinstance(details, dict) and details.get("truncation"):
        return True
    text = _response_text(result)
    return (
        "Use offset=" in text
        or "[Truncated:" in text
        or "more lines not shown" in text
        or "more lines in file" in text
    )


def _looks_like_pi_error(value: object) -> bool:
    if isinstance(value, dict) and value.get("isError"):
        return True
    text = _response_text(value).strip().lower()
    return text.startswith("error:") or "operation aborted" in text


def _looks_like_pi_image_read(value: object) -> bool:
    return _response_text(value).lstrip().startswith("Read image file [")


def _has_bounded_read_input(tool_input: object) -> bool:
    if not isinstance(tool_input, dict):
        return False
    return any(tool_input.get(key) is not None for key in ("end_line", "line_end", "limit"))


def _as_int(value: object) -> int | None:
    if value is None:
        return None
    try:
        return int(str(value))
    except (TypeError, ValueError):
        return None


def _string(value: object) -> str | None:
    if isinstance(value, str) and value:
        return value
    return None

from __future__ import annotations

import re
import shlex
from dataclasses import dataclass
from pathlib import Path
from typing import Any

_READ_TOOL_NAMES = {"Read", "NotebookRead"}


@dataclass(frozen=True)
class _ClaudeToolUse:
    parent_uuid: str | None
    tool_use_id: str | None
    payload: dict[str, Any]


@dataclass(frozen=True)
class _ClaudeToolResult:
    tool_use_id: str | None
    value: object
    is_error: bool = False


def payloads_from_claude_records(records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    tool_uses: list[_ClaudeToolUse] = []
    results_by_parent_uuid: dict[str, list[_ClaudeToolResult]] = {}
    results_by_tool_use_id: dict[str, _ClaudeToolResult] = {}

    for record in _claude_records(records):
        parent_uuid = _string(record.get("parentUuid"))
        for result in _claude_results_from_record(record):
            if result.tool_use_id:
                results_by_tool_use_id[result.tool_use_id] = result
            if parent_uuid:
                results_by_parent_uuid.setdefault(parent_uuid, []).append(result)
        tool_uses.extend(_claude_tool_uses_from_record(record))

    payloads: list[dict[str, Any]] = []
    for tool_use in tool_uses:
        payload = dict(tool_use.payload)
        result = _matching_claude_result(tool_use, results_by_tool_use_id, results_by_parent_uuid)
        if result is not None:
            tool_response = _normalize_claude_grep_response(payload, result.value)
            tool_input = _cap_claude_read_input(
                payload.get("tool_name"),
                payload.get("tool_input"),
                result,
            )
            if tool_input is None:
                continue
            payload["tool_response"] = tool_response
            payload["tool_input"] = tool_input
        else:
            tool_input = _unpaired_claude_tool_input(
                payload.get("tool_name"),
                payload.get("tool_input"),
            )
            if tool_input is None:
                continue
            payload["tool_input"] = tool_input
        payloads.append(payload)
    return payloads


def looks_like_claude_transcript(records: list[dict[str, Any]]) -> bool:
    for record in _claude_records(records):
        if _claude_tool_uses_from_record(record):
            return True
    return any(
        isinstance(record.get("message"), dict) and isinstance(record.get("sessionId"), str)
        for record in records
    )


def _matching_claude_result(
    tool_use: _ClaudeToolUse,
    results_by_tool_use_id: dict[str, _ClaudeToolResult],
    results_by_parent_uuid: dict[str, list[_ClaudeToolResult]],
) -> _ClaudeToolResult | None:
    if tool_use.tool_use_id:
        result = results_by_tool_use_id.get(tool_use.tool_use_id)
        if result is not None:
            return result
    if tool_use.parent_uuid:
        parent_results = results_by_parent_uuid.get(tool_use.parent_uuid, [])
        if len(parent_results) == 1:
            return parent_results[0]
    return None


def _unpaired_claude_tool_input(tool_name: object, tool_input: object) -> object | None:
    if tool_name not in _READ_TOOL_NAMES:
        return tool_input
    return tool_input if _has_bounded_read_input(tool_input) else None


def _claude_records(records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    normalized = []
    for record in records:
        normalized.append(record)
        data = record.get("data")
        if not isinstance(data, dict):
            continue
        child = data.get("message")
        if not isinstance(child, dict):
            continue
        merged = dict(record)
        merged.update(child)
        for key in ("cwd", "sessionId", "gitBranch", "version", "agentId", "slug"):
            if key not in merged and key in record:
                merged[key] = record[key]
            if key not in merged and key in data:
                merged[key] = data[key]
        if "prompt" not in merged and "prompt" in data:
            merged["prompt"] = data["prompt"]
        normalized.append(merged)
    return normalized


def _claude_tool_uses_from_record(record: dict[str, Any]) -> list[_ClaudeToolUse]:
    if record.get("type") != "assistant":
        return []
    parent_uuid = _string(record.get("uuid"))
    tool_uses: list[_ClaudeToolUse] = []
    for block in _claude_message_content(record):
        if block.get("type") != "tool_use":
            continue
        tool_name = _string(block.get("name"))
        tool_input = block.get("input") if isinstance(block.get("input"), dict) else {}
        tool_use_id = _string(block.get("id"))
        payload = {
            "session_id": _string(record.get("sessionId")),
            "turn_id": _string(record.get("uuid")),
            "tool_use_id": tool_use_id,
            "timestamp": _string(record.get("timestamp")),
            "cwd": _string(record.get("cwd")),
            "tool_name": tool_name,
            "tool_input": _claude_tool_input(tool_name, tool_input),
            "subagent": _string(record.get("agentId")),
            "user_request": _string(record.get("prompt")),
        }
        tool_uses.append(
            _ClaudeToolUse(
                parent_uuid=parent_uuid,
                tool_use_id=tool_use_id,
                payload={key: value for key, value in payload.items() if value is not None},
            )
        )
    return tool_uses


def _claude_results_from_record(record: dict[str, Any]) -> list[_ClaudeToolResult]:
    if record.get("type") != "user":
        return []
    fallback_result = record.get("toolUseResult")
    results = []
    for block in _claude_message_content(record):
        if block.get("type") != "tool_result":
            continue
        result = fallback_result if fallback_result is not None else block.get("content")
        results.append(
            _ClaudeToolResult(
                tool_use_id=_string(block.get("tool_use_id")),
                value=result,
                is_error=bool(block.get("is_error")),
            )
        )
    if not results and fallback_result is not None:
        results.append(
            _ClaudeToolResult(
                tool_use_id=None,
                value=fallback_result,
                is_error=_looks_like_claude_error(fallback_result),
            )
        )
    return results


def _claude_message_content(record: dict[str, Any]) -> list[dict[str, Any]]:
    message = record.get("message")
    if not isinstance(message, dict):
        return []
    content = message.get("content")
    if not isinstance(content, list):
        return []
    return [item for item in content if isinstance(item, dict)]


def _claude_tool_input(tool_name: str | None, tool_input: object) -> object:
    if tool_name not in _READ_TOOL_NAMES and tool_name != "Grep":
        return tool_input
    if not isinstance(tool_input, dict):
        return tool_input
    normalized = dict(tool_input)
    if tool_name == "Grep":
        return {
            "command": _claude_grep_command(normalized),
            "_agentcov_grep_path": _string(normalized.get("path")),
        }
    offset = normalized.pop("offset", None)
    if offset is not None and "start_line" not in normalized and "line_start" not in normalized:
        normalized["start_line"] = offset
    return normalized


def _cap_claude_read_input(
    tool_name: object, tool_input: object, result: _ClaudeToolResult
) -> object | None:
    if tool_name not in _READ_TOOL_NAMES or not isinstance(tool_input, dict):
        return tool_input
    if result.is_error or _looks_like_claude_error(result.value):
        return None
    bounds = _claude_read_result_bounds(result.value)
    if bounds is None:
        return tool_input if _has_bounded_read_input(tool_input) else None
    start, end = bounds
    if end < start:
        return tool_input
    normalized = dict(tool_input)
    normalized["start_line"] = start
    normalized["end_line"] = end
    normalized.pop("offset", None)
    normalized.pop("limit", None)
    file_path = _claude_read_result_path(result.value)
    if file_path:
        normalized.setdefault("file_path", file_path)
    return normalized


def _has_bounded_read_input(tool_input: object) -> bool:
    if not isinstance(tool_input, dict):
        return False
    return any(tool_input.get(key) is not None for key in ("end_line", "line_end", "limit"))


def _normalize_claude_grep_response(payload: dict[str, Any], result: object) -> object:
    if payload.get("tool_name") != "Grep":
        return result
    tool_input = payload.get("tool_input")
    if not isinstance(tool_input, dict):
        return result
    raw_path = _string(tool_input.get("_agentcov_grep_path"))
    if not raw_path:
        return result
    if not _looks_like_single_file_path(raw_path, _string(payload.get("cwd"))):
        return result
    text = _response_text(result)
    if not text:
        return result
    lines = []
    changed = False
    for line in text.splitlines():
        if re.match(r"^\d+(?::|-)", line):
            lines.append(f"{raw_path}:{line}")
            changed = True
        else:
            lines.append(line)
    return "\n".join(lines) if changed else result


def _looks_like_single_file_path(raw_path: str, cwd: str | None) -> bool:
    path = Path(raw_path).expanduser()
    if not path.is_absolute() and cwd:
        path = Path(cwd) / path
    if path.is_file():
        return True
    if path.exists():
        return False
    return bool(Path(raw_path).suffix)


def _claude_read_result_bounds(result: object) -> tuple[int, int] | None:
    file_result = result.get("file") if isinstance(result, dict) else None
    if isinstance(file_result, dict):
        start = _as_int(file_result.get("startLine")) or 1
        line_count = _as_int(file_result.get("numLines"))
        if line_count is None:
            content = file_result.get("content")
            if isinstance(content, str):
                line_count = _line_count(content)
        if line_count is not None and line_count > 0:
            return start, start + line_count - 1
    return _numbered_result_bounds(_response_text(result))


def _claude_read_result_path(result: object) -> str | None:
    file_result = result.get("file") if isinstance(result, dict) else None
    if not isinstance(file_result, dict):
        return None
    return _string(file_result.get("filePath"))


def _numbered_result_bounds(text: str) -> tuple[int, int] | None:
    lines = []
    for line in text.splitlines():
        match = re.match(r"^\s*(\d+)(?:\t|\s*(?:\u2192|\|))", line)
        if match:
            lines.append(int(match.group(1)))
    if not lines:
        return None
    return min(lines), max(lines)


def _line_count(text: str) -> int:
    if not text:
        return 0
    return text.count("\n") + (0 if text.endswith("\n") else 1)


def _claude_grep_command(tool_input: dict[str, Any]) -> str:
    pattern = _string(tool_input.get("pattern")) or ""
    path = _string(tool_input.get("path")) or "."
    parts = ["grep", "-R"]
    if tool_input.get("-i") or tool_input.get("case_insensitive"):
        parts.append("-i")
    if tool_input.get("-n") or tool_input.get("output_mode") == "content":
        parts.append("-n")
    parts.extend([pattern, path])
    return " ".join(shlex.quote(part) for part in parts)


def _response_text(value: object | None) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        parts: list[str] = []
        for key in ("stdout", "output", "stderr", "text", "content"):
            child = value.get(key)
            if isinstance(child, str):
                parts.append(child)
            elif isinstance(child, list):
                parts.extend(_response_text(item) for item in child)
        return "\n".join(parts)
    if isinstance(value, list):
        return "\n".join(_response_text(item) for item in value)
    return ""


def _looks_like_claude_error(value: object) -> bool:
    if isinstance(value, dict):
        error_value = value.get("error") or value.get("is_error")
        if error_value:
            return True
    text = _response_text(value).strip().lower()
    return (
        text.startswith("error:")
        or text.startswith("<tool_use_error>")
        or text.startswith("file does not exist")
        or "sibling tool call errored" in text
    )


def _as_int(value: object) -> int | None:
    if value is None:
        return None
    try:
        return int(str(value))
    except (TypeError, ValueError):
        return None


def _string(value: object) -> str | None:
    if isinstance(value, str) and value:
        return value
    return None

from __future__ import annotations

import re
import shlex
from pathlib import Path

from .git import file_line_count
from .models import LineRange, ParsedObservation
from .paths import normalize_file_path

READ_WEIGHTS = {
    "focused": 1.0,
    "head_tail": 0.8,
    "whole_file": 0.4,
    "search_hit": 0.35,
    "search_context": 0.2,
}

NO_RANGE_COMMANDS = {
    "pwd",
    "echo",
    "printf",
    "true",
    "false",
    "which",
}

SEARCH_COMMANDS = {"rg", "grep", "egrep", "fgrep"}
_XARGS_READ_COMMANDS = {"awk", "cat", "head", "sed", "tail"}


def parse_shell_command(
    command: str,
    *,
    cwd: Path,
    root: Path,
    tool_response: object | None = None,
) -> list[ParsedObservation]:
    command = command.strip()
    if not command:
        return []

    if command.startswith("for "):
        loop = _parse_simple_for_loop(command, cwd=cwd, root=root, tool_response=tool_response)
        if loop is not None:
            return loop

    observations: list[ParsedObservation] = []
    for segment in _split_top_level_segments(command):
        parsed = _parse_segment(segment, cwd=cwd, root=root, tool_response=tool_response)
        observations.extend(parsed)
    return observations


def parse_direct_tool_input(
    tool_input: object, *, cwd: Path, root: Path
) -> list[ParsedObservation]:
    if not isinstance(tool_input, dict):
        return []
    files: list[str] = []
    for key in ("path", "file", "file_path", "filename"):
        value = tool_input.get(key)
        if isinstance(value, str):
            normalized = normalize_file_path(value, cwd, root)
            if normalized:
                files.append(normalized)
    raw_files = tool_input.get("files")
    if isinstance(raw_files, list):
        for item in raw_files:
            if isinstance(item, str):
                normalized = normalize_file_path(item, cwd, root)
                if normalized:
                    files.append(normalized)

    start = _as_int(tool_input.get("start_line") or tool_input.get("line_start"))
    end = _as_int(tool_input.get("end_line") or tool_input.get("line_end"))
    offset = _as_int(tool_input.get("offset"))
    limit = _as_int(tool_input.get("limit"))
    # `offset` is the first line to read, not a count of lines to skip.
    if start is None and offset is not None:
        start = max(1, offset)
    if start is None and limit is not None:
        start = 1
    if end is None and start is not None and limit is not None:
        end = start + max(0, limit - 1)

    observations: list[ParsedObservation] = []
    for file in dict.fromkeys(files):
        line_count = file_line_count(root / file)
        range_start = start or 1
        range_end = end or line_count
        if range_end < range_start:
            range_end = range_start
        if range_end > 0:
            observations.append(
                ParsedObservation(
                    file=file,
                    ranges=[LineRange(range_start, range_end, "exact", READ_WEIGHTS["focused"])],
                    kind="read",
                    confidence="exact",
                    weight=READ_WEIGHTS["focused"],
                )
            )
    return observations


def _parse_segment(
    segment: str,
    *,
    cwd: Path,
    root: Path,
    tool_response: object | None,
) -> list[ParsedObservation]:
    try:
        tokens = shlex.split(segment)
    except ValueError as exc:
        return [_unknown(segment, f"unsupported shell syntax: {exc}")]
    if not tokens:
        return []

    first = Path(tokens[0]).name
    if first in SEARCH_COMMANDS:
        return _parse_search_output(tool_response, cwd=cwd, root=root)
    xargs_pipeline_may_read = "|" in tokens and _xargs_pipeline_may_read_source(tokens)
    if first in NO_RANGE_COMMANDS:
        if xargs_pipeline_may_read:
            return [_unknown(segment, "unsupported pipeline")]
        return []
    if first == "command" and len(tokens) >= 3 and tokens[1] == "-v":
        return []
    if first == "git" and len(tokens) >= 2 and tokens[1] in {"status", "rev-parse", "branch"}:
        return []
    if first == "find":
        if "|" in tokens:
            if xargs_pipeline_may_read:
                return [_unknown(segment, "unsupported pipeline")]
            return []
        if any(token in {"-exec", "-execdir"} for token in tokens):
            return [_unknown(segment, "unsupported find read shape")]
        return []
    if first in {"ls", "wc"}:
        if xargs_pipeline_may_read:
            return [_unknown(segment, "unsupported pipeline")]
        return []

    if "|" in tokens:
        return _parse_pipeline(tokens, cwd=cwd, root=root)
    if first == "sed":
        parsed = _parse_sed(tokens, cwd=cwd, root=root)
        return parsed or [_unknown(segment, "unsupported sed shape")]
    if first == "head":
        parsed = _parse_head(tokens, cwd=cwd, root=root)
        return parsed or [_unknown(segment, "unsupported head shape")]
    if first == "tail":
        parsed = _parse_tail(tokens, cwd=cwd, root=root)
        return parsed or [_unknown(segment, "unsupported tail shape")]
    if first == "cat":
        parsed = _parse_cat(tokens, cwd=cwd, root=root)
        return parsed or [_unknown(segment, "unsupported cat shape")]
    if first == "awk":
        parsed = _parse_awk(tokens, cwd=cwd, root=root)
        return parsed or [_unknown(segment, "unsupported awk shape")]
    if first == "sort":
        parsed = _parse_sort(tokens, cwd=cwd, root=root)
        return parsed or [_unknown(segment, "unsupported sort shape")]
    return [_unknown(segment, "unsupported command")]


def _parse_pipeline(tokens: list[str], *, cwd: Path, root: Path) -> list[ParsedObservation]:
    pipe_index = tokens.index("|")
    left = tokens[:pipe_index]
    right = tokens[pipe_index + 1 :]
    if not left or not right or Path(right[0]).name != "sed":
        return [_unknown(" ".join(tokens), "unsupported pipeline")]
    source_file = _pipeline_source_file(left, cwd=cwd, root=root)
    if not source_file:
        return [_unknown(" ".join(tokens), "unsupported pipeline input")]
    sed_ranges = _sed_ranges_from_tokens(right, file_line_count(root / source_file))
    if not sed_ranges:
        return [_unknown(" ".join(tokens), "unsupported sed pipeline range")]
    return [
        ParsedObservation(
            file=source_file,
            ranges=sed_ranges,
            kind="read",
            confidence="exact",
            weight=READ_WEIGHTS["focused"],
        )
    ]


def _xargs_pipeline_may_read_source(tokens: list[str]) -> bool:
    for pipe_index, token in enumerate(tokens):
        if token != "|":
            continue
        command_names = {Path(item).name for item in tokens[pipe_index + 1 :]}
        if "xargs" in command_names and _XARGS_READ_COMMANDS.intersection(command_names):
            return True
    return False


def _pipeline_source_file(tokens: list[str], *, cwd: Path, root: Path) -> str | None:
    first = Path(tokens[0]).name
    if first == "cat":
        return _last_path_token(tokens[1:], cwd=cwd, root=root, value_options=frozenset())
    if first == "nl":
        candidates = [token for token in tokens[1:] if not token.startswith("-")]
        if candidates:
            return normalize_file_path(candidates[-1], cwd, root)
    return None


def _parse_sed(tokens: list[str], *, cwd: Path, root: Path) -> list[ParsedObservation]:
    source_file = _sed_source_file(tokens, cwd=cwd, root=root)
    if not source_file:
        return []
    ranges = _sed_ranges_from_tokens(tokens, file_line_count(root / source_file))
    if not ranges:
        return []
    return [
        ParsedObservation(
            file=source_file,
            ranges=ranges,
            kind="read",
            confidence="exact",
            weight=READ_WEIGHTS["focused"],
        )
    ]


def _parse_head(tokens: list[str], *, cwd: Path, root: Path) -> list[ParsedObservation]:
    source_file = _last_path_token(tokens[1:], cwd=cwd, root=root)
    if not source_file or _has_byte_count_arg(tokens):
        return []
    count = _line_count_arg(tokens, default=10)
    if count <= 0:
        return []
    line_count = file_line_count(root / source_file)
    end = min(count, line_count) if line_count else count
    return [
        ParsedObservation(
            file=source_file,
            ranges=[LineRange(1, max(1, end), "exact", READ_WEIGHTS["head_tail"])],
            kind="read",
            confidence="exact",
            weight=READ_WEIGHTS["head_tail"],
        )
    ]


def _parse_tail(tokens: list[str], *, cwd: Path, root: Path) -> list[ParsedObservation]:
    source_file = _last_path_token(tokens[1:], cwd=cwd, root=root)
    if not source_file or _has_byte_count_arg(tokens):
        return []
    line_count = file_line_count(root / source_file)
    if line_count <= 0:
        return [_unknown(" ".join(tokens), "tail requires file line count")]
    plus_start = _tail_plus_start_arg(tokens)
    if plus_start is not None:
        start = min(max(1, plus_start), line_count)
    else:
        count = _line_count_arg(tokens, default=10)
        if count <= 0:
            return []
        start = max(1, line_count - count + 1)
    return [
        ParsedObservation(
            file=source_file,
            ranges=[LineRange(start, line_count, "exact", READ_WEIGHTS["head_tail"])],
            kind="read",
            confidence="exact",
            weight=READ_WEIGHTS["head_tail"],
        )
    ]


def _parse_cat(tokens: list[str], *, cwd: Path, root: Path) -> list[ParsedObservation]:
    source_file = _last_path_token(tokens[1:], cwd=cwd, root=root, value_options=frozenset())
    if not source_file:
        return []
    line_count = file_line_count(root / source_file)
    if line_count <= 0:
        return []
    return [
        ParsedObservation(
            file=source_file,
            ranges=[LineRange(1, line_count, "exact", READ_WEIGHTS["whole_file"])],
            kind="read",
            confidence="exact",
            weight=READ_WEIGHTS["whole_file"],
        )
    ]


def _parse_awk(tokens: list[str], *, cwd: Path, root: Path) -> list[ParsedObservation]:
    if len(tokens) < 3:
        return []
    script = tokens[1]
    source_file = _last_path_token(tokens[2:], cwd=cwd, root=root)
    if not source_file:
        return []
    ranges: list[LineRange] = []
    match = re.search(r"NR\s*>=\s*(\d+)\s*&&\s*NR\s*<=\s*(\d+)", script)
    if match:
        ranges.append(
            LineRange(int(match.group(1)), int(match.group(2)), "exact", READ_WEIGHTS["focused"])
        )
    match = re.search(r"NR\s*==\s*(\d+)", script)
    if match:
        line = int(match.group(1))
        ranges.append(LineRange(line, line, "exact", READ_WEIGHTS["focused"]))
    if not ranges:
        return []
    return [
        ParsedObservation(
            file=source_file,
            ranges=ranges,
            kind="read",
            confidence="exact",
            weight=READ_WEIGHTS["focused"],
        )
    ]


def _parse_sort(tokens: list[str], *, cwd: Path, root: Path) -> list[ParsedObservation]:
    source_file = _last_path_token(
        tokens[1:],
        cwd=cwd,
        root=root,
        value_options=frozenset(
            {
                "-k",
                "--key",
                "-o",
                "--output",
                "-S",
                "--buffer-size",
                "-t",
                "--field-separator",
                "-T",
                "--temporary-directory",
            }
        ),
    )
    if not source_file:
        return []
    line_count = file_line_count(root / source_file)
    if line_count <= 0:
        return []
    return [
        ParsedObservation(
            file=source_file,
            ranges=[LineRange(1, line_count, "exact", READ_WEIGHTS["whole_file"])],
            kind="read",
            confidence="exact",
            weight=READ_WEIGHTS["whole_file"],
        )
    ]


def _parse_search_output(
    tool_response: object | None, *, cwd: Path, root: Path
) -> list[ParsedObservation]:
    text = _response_text(tool_response)
    if not text:
        return []
    by_file: dict[str, dict[int, float]] = {}
    for line in text.splitlines():
        match = re.match(r"^(.+?)(?::|-)(\d+)(?P<trailing>[:\-])", line)
        if not match:
            continue
        rel = normalize_file_path(match.group(1), cwd, root)
        if not rel:
            continue
        line_number = int(match.group(2))
        weight = (
            READ_WEIGHTS["search_context"]
            if match.group("trailing") == "-"
            else READ_WEIGHTS["search_hit"]
        )
        previous = by_file.setdefault(rel, {}).get(line_number, 0.0)
        by_file[rel][line_number] = max(previous, weight)
    observations = []
    for rel, lines in sorted(by_file.items()):
        ranges = [LineRange(line, line, "exact", weight) for line, weight in sorted(lines.items())]
        observations.append(
            ParsedObservation(
                file=rel,
                ranges=ranges,
                kind="search_seen",
                confidence="exact",
                weight=READ_WEIGHTS["search_hit"],
            )
        )
    return observations


def _response_text(value: object | None) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        parts: list[str] = []
        for key in ("stdout", "output", "stderr", "text", "content"):
            child = value.get(key)
            if isinstance(child, str):
                parts.append(child)
            elif isinstance(child, list):
                parts.extend(_response_text(item) for item in child)
        return "\n".join(parts)
    if isinstance(value, list):
        return "\n".join(_response_text(item) for item in value)
    return ""


def _sed_ranges_from_tokens(tokens: list[str], line_count: int) -> list[LineRange]:
    expressions: list[str] = []
    index = 1
    while index < len(tokens):
        token = [REDACTED]]
        if token in {"-n", "--quiet", "--silent"}:
            index += 1
            continue
        if token in {"-e", "--expression"} and index + 1 < len(tokens):
            expressions.append(tokens[index + 1])
            index += 2
            continue
        if re.search(r"\d+\s*(?:,\s*(?:\d+|\$))?\s*p", token):
            expressions.append(token)
        index += 1

    ranges: list[LineRange] = []
    for expression in expressions:
        for part in expression.split(";"):
            part = part.strip()
            match = re.search(r"(\d+)\s*,\s*(\d+|\$)\s*p", part)
            if match:
                start = int(match.group(1))
                raw_end = match.group(2)
                if raw_end == "$":
                    if line_count <= 0:
                        continue
                    end = line_count
                else:
                    end = int(raw_end)
                ranges.append(LineRange(start, end, "exact", READ_WEIGHTS["focused"]).normalized())
                continue
            match = re.search(r"(\d+)\s*p", part)
            if match:
                line = int(match.group(1))
                ranges.append(LineRange(line, line, "exact", READ_WEIGHTS["focused"]))
    return ranges


def _sed_source_file(tokens: list[str], *, cwd: Path, root: Path) -> str | None:
    skip_next = False
    candidates: list[str] = []
    for index, token in enumerate(tokens[1:], start=1):
        if skip_next:
            skip_next = False
            continue
        if _redirection_consumes_next(token):
            skip_next = True
            continue
        if _is_attached_redirection(token):
            continue
        if token in {"-e", "--expression", "-f", "--file"}:
            skip_next = True
            continue
        if token in {"-n", "--quiet", "--silent"} or token.startswith("-"):
            continue
        if re.search(r"\d+\s*(?:,\s*(?:\d+|\$))?\s*p", token):
            continue
        if index > 0:
            candidates.append(token)
    if not candidates:
        return None
    return normalize_file_path(candidates[-1], cwd, root)


def _last_path_token(
    tokens: list[str],
    *,
    cwd: Path,
    root: Path,
    value_options: frozenset[str] = frozenset({"-n", "-c"}),
) -> str | None:
    candidates = []
    skip_next = False
    for token in tokens:
        if skip_next:
            skip_next = False
            continue
        if _redirection_consumes_next(token):
            skip_next = True
            continue
        if _is_attached_redirection(token):
            continue
        if token in value_options:
            skip_next = True
            continue
        if token.startswith("-"):
            continue
        candidates.append(token)
    if not candidates:
        return None
    return normalize_file_path(candidates[-1], cwd, root)


def _line_count_arg(tokens: list[str], default: int) -> int:
    for index, token in enumerate(tokens[1:], start=1):
        if token in {"-n", "--lines"} and index + 1 < len(tokens):
            value = _as_int(tokens[index + 1])
            if value is not None:
                return value
        if token.startswith("-n") and len(token) > 2:
            value = _as_int(token[2:])
            if value is not None:
                return value
        if token.startswith("--lines="):
            value = _as_int(token.removeprefix("--lines="))
            if value is not None:
                return value
        if re.match(r"^-\d+$", token):
            return abs(int(token))
    return default


def _has_byte_count_arg(tokens: list[str]) -> bool:
    for token in tokens[1:]:
        if token in {"-c", "--bytes"} or token.startswith(("-c", "--bytes=")):
            return True
    return False


def _tail_plus_start_arg(tokens: list[str]) -> int | None:
    for index, token in enumerate(tokens[1:], start=1):
        if token in {"-n", "--lines"} and index + 1 < len(tokens):
            value = _plus_int(tokens[index + 1])
            if value is not None:
                return value
        if token.startswith("-n+"):
            value = _plus_int(token[2:])
            if value is not None:
                return value
        if token.startswith("--lines=+"):
            value = _plus_int(token.removeprefix("--lines="))
            if value is not None:
                return value
        value = _plus_int(token)
        if value is not None:
            return value
    return None


def _plus_int(value: str) -> int | None:
    if re.match(r"^\+\d+$", value):
        return int(value[1:])
    return None


def _redirection_consumes_next(token: str) -> bool:
    return token in {">", ">>", "<", "<<", "2>", "2>>", "1>", "1>>", "&>", ">&"}


def _is_attached_redirection(token: str) -> bool:
    return re.match(r"^(?:\d*)?(?:>{1,2}|<<?|&>|\>&).+", token) is not None


def _parse_simple_for_loop(
    command: str,
    *,
    cwd: Path,
    root: Path,
    tool_response: object | None,
) -> list[ParsedObservation] | None:
    match = re.match(r"for\s+(\w+)\s+in\s+(.+?);\s*do\s+(.+?);\s*done\s*$", command)
    if not match:
        return None
    var_name, raw_items, body = match.groups()
    try:
        items = shlex.split(raw_items)
    except ValueError:
        return [_unknown(command, "unsupported for-loop item syntax")]
    observations: list[ParsedObservation] = []
    for item in items:
        expanded = body.replace(f'"${var_name}"', shlex.quote(item))
        expanded = expanded.replace(f"'${var_name}'", shlex.quote(item))
        expanded = expanded.replace(f"${var_name}", shlex.quote(item))
        observations.extend(
            parse_shell_command(expanded, cwd=cwd, root=root, tool_response=tool_response)
        )
    return observations


def _split_top_level_segments(command: str) -> list[str]:
    segments: list[str] = []
    current: list[str] = []
    quote: str | None = None
    index = 0
    while index < len(command):
        char = command[index]
        if quote:
            current.append(char)
            if char == quote:
                quote = None
            index += 1
            continue
        if char in {"'", '"'}:
            quote = char
            current.append(char)
            index += 1
            continue
        operator = command[index : index + 2]
        if (
            char in {";", "\n"}
            or operator in {"&&", "||"}
            or _is_background_operator(command, index)
        ):
            segment = "".join(current).strip()
            if segment:
                segments.append(segment)
            current = []
            index += 2 if operator in {"&&", "||"} else 1
            continue
        current.append(char)
        index += 1
    segment = "".join(current).strip()
    if segment:
        segments.append(segment)
    return segments


def _is_background_operator(command: str, index: int) -> bool:
    if command[index] != "&":
        return False
    if command[index : index + 2] in {"&&", "&>"}:
        return False
    return index == 0 or command[index - 1] != ">"


def _unknown(command: str, reason: str) -> ParsedObservation:
    return ParsedObservation(
        file=None,
        ranges=[],
        kind="unknown",
        confidence="unknown",
        weight=0.0,
        reason=reason,
    )


def _as_int(value: object) -> int | None:
    if value is None:
        return None
    try:
        return int(str(value))
    except (TypeError, ValueError):
        return None

from __future__ import annotations

import json
